    for n in names:
        p=os.path.join(dirpath,n)
        if os.path.basename(p)=='result.md': continue
        files.append(p)
patterns={
 'sk-':r'sk-',
 'Bearer':r'Bearer',
 'Authorization':r'Authorization',
 'api_key':r'api_key',
 'synthetic_env_value':r'agms-canary-7f3a9c-synthetic-token',
}
longre=re.compile(r'[A-Za-z0-9_\\-]{32,}')
uuidre=re.compile(r'[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}')
