    try:
        b=open(p,'rb').read(); s=b.decode('utf-8','ignore')
    except Exception as e:
        print('READ_ERROR',p,e); continue
    counts={k:len(re.findall(v,s)) for k,v in patterns.items()}
    longs=[]
