        print(os.path.relpath(p,root), 'counts='+json.dumps(counts,sort_keys=True), 'long_non_uuid_count='+str(len(longs)))
        # classify long tokens by shape only
        shapes={}
        for t in longs:
            shape='hex' if re.fullmatch(r'[0-9a-fA-F]+',t) else ('base64ish' if re.fullmatch(r'[A-Za-z0-9_\\-]+',t) else 'other')
            shapes[shape]=shapes.get(shape,0)+1
        print('  long_shapes',shapes)
